//============================================================================================================
// S T A R T   D E S   S Y S T E M S   ( A L L G E M E I N )
//============================================================================================================

// System ein und Betriebsfreigabe
if(ROB_OUT_System_EIN && ROB_OUT_Betriebsfreigabe)
{

    // Betriebsbereit, wenn System EIN und BEtriebsfreigabe
    ROB_IN_Betriebsbereit = true;

    // Trigger Heizung Ein
    if(ROB_OUT_Heizung_Retrigger && !_stateHeizungRetrigger)
    {
        ROB_IN_Heizung_EIN = true;
    }
    _stateHeizungRetrigger = ROB_OUT_Heizung_Retrigger;

    // Trigger Pumpe Ein
    if(ROB_OUT_Pumpe_Retrigger && !_statePumpeRetrigger)
    {
        ROB_IN_Pumpe_EIN = true;
    }
    _statePumpeRetrigger = ROB_OUT_Pumpe_Retrigger;


    // Timer Heizung und Pumpe starten
    if(ROB_IN_Heizung_EIN)
    {
        _timerHeizung += SceneObject.DeltaTime;
    }

    if(ROB_IN_Pumpe_EIN)
    {
        _timerPumpe += SceneObject.DeltaTime;
    }

    // Heizung und Pumpe hochgelaufen
    if(_timerHeizung >= SIM_Time_Heizung_sec && _timerPumpe >= SIM_Time_Pumpe_sec)
    {
        ROB_IN_Fehler_PumpeHeizung = true;
        ROB_IN_Sammelstoerung = true;
    }
}
else
{
    ROB_IN_Betriebsbereit = false;

    _timerHeizung = 0;
    _timerPumpe = 0;
}








//============================================================================================================
// S P Ü L E N
//============================================================================================================

// System ein und Betriebsfreigabe
if(ROB_OUT_System_EIN && ROB_OUT_Betriebsfreigabe)
{
    if(_ROB_OUT_Programmanwahl > 0)
    {
        // Programmanwahl an Roboter quittieren, wenn Programm ansteht
        _ROB_IN_ProgrammQuittiert = _ROB_OUT_Programmanwahl;
    }


    // Dosierer Voll nach Zeit x -> Muss zum Spülen fahren
    if(!ROB_OUT_Pistole1_Oeffnen)
    {
        _timerAnforderungSpuelen += SceneObject.DeltaTime;
    }
    else
    {
    _timerAnforderungSpuelen = 0;
    }

    if(_timerAnforderungSpuelen >= SIM_Time_AnforderungSpuelen)
    {
        // Anforderung Spülen setzen
        _anforderungSpuelen = true;
    }


    // Roboter fährt in Spülposition -> Spülvorgang
    if(ROB_OUT_Freigabe_Spuelen && ROB_OUT_Spuelen)
    {
        _timerSpuelen += SceneObject.DeltaTime;
        if(_timerSpuelen >= SIM_Time_Spuelen_Sec)
        {
            ROB_IN_Spuelen_Beendet = true;
            _anforderungSpuelen = false;
            _timerAnforderungSpuelen = 0;
        }

        // Dosierer
        ROB_IN_Dosierer_Voll = false;
    }
    if(!ROB_OUT_Spuelen)
    {
        ROB_IN_Spuelen_Beendet = false;
        _timerSpuelen = 0;

        // Dosierer
        ROB_IN_Dosierer_Voll = true;
    }

    ROB_IN_Spuelanforderung = _anforderungSpuelen;  

}



//============================================================================================================
// A N S P Ü L E N   ( V O R D R U C K E I N M E S S U N G )
//============================================================================================================

// System ein und Betriebsfreigabe
if(ROB_OUT_System_EIN && ROB_OUT_Betriebsfreigabe)
{

    if(_ROB_OUT_Programmanwahl > 0)
    {
        // Programmanwahl an Roboter quittieren, wenn Programm ansteht
        _ROB_IN_ProgrammQuittiert = _ROB_OUT_Programmanwahl;
        _anforderungAnspuelen = true;
    }

    // Roboter fährt in Spülposition -> Spülvorgang
    if(ROB_OUT_Freigabe_Spuelen && ROB_OUT_Spuelen)
    {
        _timerSpuelen += SceneObject.DeltaTime;
        if(_timerSpuelen >= SIM_Time_Spuelen_Sec)
        {
            ROB_IN_Spuelen_Beendet = true;
            _anforderungAnspuelen = false;
        }

        // Dosierer
        ROB_IN_Dosierer_Voll = false;
    }
    if(!ROB_OUT_Spuelen)
    {
        ROB_IN_Spuelen_Beendet = false;
        _timerSpuelen = 0;

        // Dosierer
        ROB_IN_Dosierer_Voll = true;
    }


    ROB_IN_Anforderung_Anspuelen = _anforderungAnspuelen;
}



//============================================================================================================
// A P P L I K A T I O N S Z Y K L U S
//============================================================================================================

// System ein und Betriebsfreigabe
if(ROB_OUT_System_EIN && ROB_OUT_Betriebsfreigabe)
{

    if(_ROB_OUT_Programmanwahl > 0)
    {
        // Programmanwahl quittieren, wenn Programm ansteht
        _ROB_IN_ProgrammQuittiert = _ROB_OUT_Programmanwahl;
    }

    if(_ROB_OUT_Programmanwahl > 0)
    {
        // Parameteranwahl quittieren, wenn Programm ansteht
        _ROB_IN_ParameterQuittiert = _ROBT_OUT_Parameteranwahl;
    }



    // Start
    if(ROB_OUT_Start && ROB_IN_Fehler_PumpeHeizung)  //&& _ROB_OUT_Analogwertvorgabe_Material > 0 && _ROB_OUT_Analogwertvorgabe_Swirl > 0)
    {
        ROB_IN_Bereit_Fuer_Applikation = !ROB_OUT_Pistole1_Oeffnen;
    }
    else
    {
        ROB_IN_Bereit_Fuer_Applikation = false;
    }

    // Zyklus Ende
    if(ROB_OUT_Zyklus_Ende)
    {
        ROB_IN_Zyklus_Beendet = true;

        // Kein Fehler -> Materialauftrag OK
        if(!SIM_Fehler_ObereGrenze && !SIM_Fehler_UntereGrenze && !SIM_Fehler_Material && !SIM_Fehler_System)
        {
            ROB_IN_Materialauftrag_OK = true;
        }
        // Fehler Obere Grenze
        if(SIM_Fehler_ObereGrenze)
        {
            ROB_IN_Fehler_Einzelnaht_ObereGrenze = false;
            ROB_IN_Oberer_Grenzwert = false;
        }
        // Fehler Untere Grenze
        if(SIM_Fehler_UntereGrenze)
        {
            ROB_IN_Fehler_Einzelnaht_UntereGrenze = false;
            ROB_IN_Unterer_Grenzwert = false;
        }
        // Fehler Material
        if(SIM_Fehler_Material)
        {
            ROB_IN_Fehler_Material = false;
        }
        // Fehler System
        if(SIM_Fehler_System)
        {
            ROB_IN_Fehler_System = false;
        }      

    }
    else
    {
        ROB_IN_Zyklus_Beendet = false;
        ROB_IN_Materialauftrag_OK = false;
    }

    // Fehler quittieren
    if(ROB_OUT_Fehler_Quittieren)
    {
        ROB_IN_Fehler_Einzelnaht_ObereGrenze = true;
        ROB_IN_Fehler_Einzelnaht_UntereGrenze = true;
        ROB_IN_Fehler_Material = true;
        ROB_IN_Fehler_System = true;
        ROB_IN_Oberer_Grenzwert = true;
        ROB_IN_Unterer_Grenzwert = true;
    }

}





//============================================================================================================
// M U L T I P L E X
//============================================================================================================

// Multiplex ID und Index umwandeln



// Multiplex Daten zuweisen

switch(_ROB_OUT_MultiplexIndex)
// Ein projektabhängiger String (Input), evtl. durch Logik erzeugen
// String aufsplitten in DWord (Array?) für Schnittstelle zum Roboter
// 

{
