// Multiplex Adresse und Index quittieren
_ROB_IN_Multiplex_Adressquittierung = _ROB_OUT_MultiplexAdresse;
_ROB_IN_Multiplex_Indexquittierung = _ROB_OUT_MultiplexIndex;
